  shape: f32,
  shape_count: f32,
  tint: f32,
  time: f32,
  quality: f32,
  yaw: f32,
  pitch: f32,
  radius: f32,
  dispersion: f32,
  strip_angle: f32,
  floor_luminance: f32,
